package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallUser;
import com.fixflow.mall.repo.UserRepository;
import org.springframework.stereotype.Service;

@Service
public class UserService {

    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public String getNickname(Long userId) {
        MallUser user = userRepository.findById(userId).orElseThrow();
        // BUG-001: profileJson may be null, direct split causes NullPointerException.
        return user.getProfileJson().split(":")[1];
    }

}

