package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallUser;
import com.fixflow.mall.repo.UserRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    @Test
    @DisplayName("正向测试：当profileJson包含冒号时，正确返回冒号后的部分")
    void testGetNickname_WhenProfileJsonContainsColon_ReturnsCorrectNickname() {
        // 准备测试数据
        MallUser mockUser = mock(MallUser.class);
        when(mockUser.getProfileJson()).thenReturn("nickname:John");
        when(userRepository.findById(anyLong())).thenReturn(Optional.of(mockUser));

        // 执行测试
        String result = userService.getNickname(1L);

        // 验证结果
        assertEquals("John", result);
        verify(userRepository).findById(1L);
    }

    @Test
    @DisplayName("边界测试：当profileJson为null时，返回null不抛出NullPointerException")
    void testGetNickname_WhenProfileJsonIsNull_ReturnsNull() {
        // 准备测试数据
        MallUser mockUser = mock(MallUser.class);
        when(mockUser.getProfileJson()).thenReturn(null);
        when(userRepository.findById(anyLong())).thenReturn(Optional.of(mockUser));

        // 执行测试
        String result = userService.getNickname(1L);

        // 验证结果
        assertNull(result);
        verify(userRepository).findById(1L);
    }

    @Test
    @DisplayName("边界测试：当profileJson不包含冒号时，返回null")
    void testGetNickname_WhenProfileJsonDoesNotContainColon_ReturnsNull() {
        // 准备测试数据
        MallUser mockUser = mock(MallUser.class);
        when(mockUser.getProfileJson()).thenReturn("no-colon-string");
        when(userRepository.findById(anyLong())).thenReturn(Optional.of(mockUser));

        // 执行测试
        String result = userService.getNickname(1L);

        // 验证结果
        assertNull(result);
        verify(userRepository).findById(1L);
    }

    @Test
    @DisplayName("异常测试：当用户不存在时，抛出NoSuchElementException")
    void testGetNickname_WhenUserNotFound_ThrowsException() {
        // 准备测试数据
        when(userRepository.findById(anyLong())).thenReturn(Optional.empty());

        // 执行和验证异常
        assertThrows(java.util.NoSuchElementException.class, () -> userService.getNickname(1L));
        verify(userRepository).findById(1L);
    }
}
